/**
 * Swift Woo - Variation & Multi-Color Picker JS
 * - Keeps WooCommerce native <select> & variations_form 100% intact (visually hidden)
 * - Auto-selects first in-stock variation on load
 * - Renders clickable color swatches & pack/pis pill buttons
 * - Dynamically shows 1/2/3 color selectors based on selected pis
 * - Passes colors via hidden inputs → saved to cart/order meta via PHP hooks
 * - Zero eval(), exec(), or obfuscated code — scanner-safe
 * @version 1.0.0
 */
( function () {
	'use strict';

	// Guard: only run on single product pages with variation form
	const variationForm = document.querySelector( 'form.variations_form' );
	if ( ! variationForm ) return;

	/* ------------------------------------------------------------------
	 * 1. Build Swatches & Pis Buttons from native <select> elements
	 * ------------------------------------------------------------------ */
	const selects = variationForm.querySelectorAll( 'select[data-attribute_name], select[name^="attribute_"]' );

	selects.forEach( function ( select ) {
		const wrapper   = select.closest( 'tr' ) || select.closest( '.value' ) || select.parentElement;
		const attrName  = ( select.getAttribute( 'data-attribute_name' ) || select.getAttribute( 'name' ) || '' ).toLowerCase();
		const isPis     = /pis|pack|quantity|qty/i.test( attrName );
		const isColor   = /color|colour|rang/i.test( attrName );

		// Hide native select visually (keep it in DOM for WooCommerce events)
		select.style.cssText = 'position:absolute;width:1px;height:1px;overflow:hidden;opacity:0;pointer-events:none;';
		select.setAttribute( 'aria-hidden', 'true' );

		// Build label display
		const labelDisplay = document.createElement( 'div' );
		labelDisplay.className = 'swift-swatch-label';
		labelDisplay.setAttribute( 'aria-live', 'polite' );

		// Build button container
		const btnContainer = document.createElement( 'div' );
		btnContainer.className = isPis ? 'swift-pis-buttons' : 'swift-color-swatches';
		btnContainer.setAttribute( 'role', 'group' );
		btnContainer.setAttribute( 'aria-label', attrName.replace( /attribute_/i, '' ) );

		const options = Array.from( select.options ).filter( o => o.value !== '' );

		options.forEach( function ( option ) {
			const btn = document.createElement( 'button' );
			btn.type  = 'button';
			btn.className = isPis ? 'swift-pis-btn' : 'swift-color-swatch';
			btn.textContent = option.textContent.trim();
			btn.dataset.value = option.value;
			btn.setAttribute( 'aria-pressed', 'false' );

			// Color swatch: apply background color if value looks like a color name
			if ( isColor ) {
				btn.style.backgroundColor = option.value.toLowerCase();
				btn.setAttribute( 'aria-label', option.textContent.trim() );
				btn.textContent = '';
			}

			// Disabled if option is disabled (out of stock)
			if ( option.disabled ) {
				btn.disabled = true;
				btn.setAttribute( 'aria-disabled', 'true' );
				btn.classList.add( 'is-disabled' );
			}

			btn.addEventListener( 'click', function () {
				selectSwatch( select, btnContainer, btn, labelDisplay, attrName );
			} );

			btnContainer.appendChild( btn );
		} );

		wrapper.appendChild( labelDisplay );
		wrapper.appendChild( btnContainer );

		// Auto-select first enabled option
		const firstEnabled = options.find( o => ! o.disabled );
		if ( firstEnabled ) {
			const firstBtn = btnContainer.querySelector( `[data-value="${ CSS.escape( firstEnabled.value ) }"]` );
			if ( firstBtn ) {
				selectSwatch( select, btnContainer, firstBtn, labelDisplay, attrName );
			}
		}
	} );

	/* ------------------------------------------------------------------
	 * 2. Swatch selection — triggers native WooCommerce `change` event
	 * ------------------------------------------------------------------ */
	function selectSwatch( select, container, activeBtn, labelDisplay, attrName ) {
		container.querySelectorAll( 'button' ).forEach( function ( b ) {
			b.classList.remove( 'is-active' );
			b.setAttribute( 'aria-pressed', 'false' );
		} );
		activeBtn.classList.add( 'is-active' );
		activeBtn.setAttribute( 'aria-pressed', 'true' );

		// Update native <select> value
		select.value = activeBtn.dataset.value;

		// Update label display
		labelDisplay.textContent = select.previousElementSibling
			? select.previousElementSibling.textContent.trim() + ': ' + activeBtn.dataset.value
			: activeBtn.dataset.value;

		// Dispatch native WooCommerce change event (keeps Pixel & price update intact)
		const event = new Event( 'change', { bubbles: true } );
		select.dispatchEvent( event );

		// If pis button clicked, update multi-color selectors
		if ( /pis|pack|quantity|qty/i.test( attrName ) ) {
			const count = parseInt( activeBtn.dataset.value, 10 );
			if ( ! isNaN( count ) && count >= 1 && count <= 10 ) {
				updateMultiColorPickers( count );
			}
		}
	}

	/* ------------------------------------------------------------------
	 * 3. Multi-Piece Color Pickers (1/2/3 Pis → 1/2/3 color dropdowns)
	 * ------------------------------------------------------------------ */
	const multiColorContainer = document.createElement( 'div' );
	multiColorContainer.id    = 'swift-multi-color-container';
	variationForm.appendChild( multiColorContainer );

	// Collect available colors from the main color <select>
	function getAvailableColors() {
		const colorSelect = variationForm.querySelector( 'select[data-attribute_name*="color"], select[name*="color"]' );
		if ( ! colorSelect ) return [];
		return Array.from( colorSelect.options )
			.filter( o => o.value !== '' )
			.map( o => ( { value: o.value, label: o.textContent.trim() } ) );
	}

	function updateMultiColorPickers( count ) {
		multiColorContainer.innerHTML = '';

		if ( count < 2 ) return; // 1 pis = main color select is enough

		const colors = getAvailableColors();
		if ( ! colors.length ) return;

		for ( let i = 0; i < count; i++ ) {
			const wrapper = document.createElement( 'div' );
			wrapper.className = 'swift-extra-color-row';

			const label = document.createElement( 'label' );
			label.htmlFor  = 'swift-color-pick-' + i;
			label.textContent = ( i + 1 ) + 'st Pis Color:';
			if ( i === 1 ) label.textContent = ( i + 1 ) + 'nd Pis Color:';
			if ( i === 2 ) label.textContent = ( i + 1 ) + 'rd Pis Color:';
			if ( i  > 2 ) label.textContent = ( i + 1 ) + 'th Pis Color:';

			// Color swatch row for each pis
			const swatchRow = document.createElement( 'div' );
			swatchRow.className = 'swift-color-swatches swift-extra-swatches';
			swatchRow.setAttribute( 'role', 'group' );
			swatchRow.setAttribute( 'aria-label', label.textContent );

			// Hidden input to pass color to PHP
			const hidden = document.createElement( 'input' );
			hidden.type  = 'hidden';
			hidden.name  = 'swift_colors[' + i + ']';
			hidden.id    = 'swift-color-pick-' + i;

			colors.forEach( function ( color ) {
				const btn = document.createElement( 'button' );
				btn.type  = 'button';
				btn.className = 'swift-color-swatch';
				btn.dataset.value = color.value;
				btn.style.backgroundColor = color.value.toLowerCase();
				btn.setAttribute( 'aria-label', color.label );
				btn.setAttribute( 'aria-pressed', 'false' );

				btn.addEventListener( 'click', function () {
					swatchRow.querySelectorAll( 'button' ).forEach( b => {
						b.classList.remove( 'is-active' );
						b.setAttribute( 'aria-pressed', 'false' );
					} );
					btn.classList.add( 'is-active' );
					btn.setAttribute( 'aria-pressed', 'true' );
					hidden.value = color.value;
				} );

				swatchRow.appendChild( btn );
			} );

			// Auto-select first color
			if ( colors.length ) {
				const firstBtn = swatchRow.querySelector( 'button' );
				if ( firstBtn ) {
					firstBtn.classList.add( 'is-active' );
					firstBtn.setAttribute( 'aria-pressed', 'true' );
					hidden.value = colors[0].value;
				}
			}

			wrapper.appendChild( label );
			wrapper.appendChild( swatchRow );
			wrapper.appendChild( hidden );
			multiColorContainer.appendChild( wrapper );
		}
	}

	/* ------------------------------------------------------------------
	 * 4. BFcache Fix — reset button states on browser back navigation
	 * ------------------------------------------------------------------ */
	window.addEventListener( 'pageshow', function ( e ) {
		if ( e.persisted ) {
			// Reset Buy Now button loading state
			const buyBtns = document.querySelectorAll( '.swift-buy-now-btn' );
			buyBtns.forEach( function ( btn ) {
				btn.disabled = false;
				btn.classList.remove( 'is-loading' );
			} );
		}
	} );

} )();
